<?php
use App\Models\AppSetting; use App\Models\DiscordBot; use App\Models\DiscordChannel; use App\Models\DiscordGuild; use App\Models\VoiceAudioClip; use App\Models\VoiceEvent; use App\Models\VoiceReport; use App\Models\VoiceTranscript; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
it('rejects requests without a service token',fn()=>$this->getJson('/api/v1/internal/bots')->assertUnauthorized());
it('never exposes tokens in the bot listing',function(){config(['services.worker.token'=>'secret']);DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$this->withToken('secret')->getJson('/api/v1/internal/bots')->assertOk()->assertJsonMissing(['token'=>'discord-secret']);});
it('returns monitored voice channel assignments for an active bot',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'General','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-2','name'=>'Logs','type'=>'text','is_monitored'=>false]);$this->withToken('secret')->getJson("/api/v1/internal/bots/{$bot->id}/assignments")->assertOk()->assertJsonPath('data.channels.0.channel_discord_id','channel-1')->assertJsonPath('data.channels.0.guild_discord_id','guild-1')->assertJsonCount(1,'data.channels');});
it('loads a channel guild through the discord guild foreign key',function(){$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$channel=DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'General','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);expect($channel->fresh()->guild->is($guild))->toBeTrue();});
it('allows one bot to monitor several voice channels in the same guild',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'General','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-2','name'=>'AFK','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$this->withToken('secret')->getJson("/api/v1/internal/bots/{$bot->id}/assignments")->assertOk()->assertJsonCount(2,'data.channels');});
it('prevents text channels from being monitored',function(){$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);expect(fn()=>DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'Textuel','type'=>'text','is_monitored'=>true,'discord_bot_id'=>$bot->id]))->toThrow(ValidationException::class);});
it('prunes voice events older than twenty four hours when a new event arrives',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'Général','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);VoiceEvent::query()->create(['discord_guild_id'=>$guild->id,'type'=>'voice_join','payload'=>[],'occurred_at'=>now()->subHours(25)]);VoiceEvent::query()->create(['discord_guild_id'=>$guild->id,'type'=>'voice_leave','payload'=>[],'occurred_at'=>now()->subHours(2)]);$this->withToken('secret')->postJson('/api/v1/internal/events',['guild_discord_id'=>'guild-1','channel_discord_id'=>'channel-1','discord_user_id'=>'user-1','type'=>'voice_join','payload'=>['display_name'=>'User'],'occurred_at'=>now()->toISOString()])->assertCreated();expect(VoiceEvent::query()->where('occurred_at','<',now()->subDay())->count())->toBe(0)->and(VoiceEvent::query()->count())->toBe(2);});
it('accepts timeline voice state events',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'Général','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$this->withToken('secret')->postJson('/api/v1/internal/events',['guild_discord_id'=>'guild-1','channel_discord_id'=>'channel-1','discord_user_id'=>'user-1','type'=>'screen_share_start','payload'=>['display_name'=>'User','streaming'=>true],'occurred_at'=>now()->toISOString()])->assertCreated();expect(VoiceEvent::query()->where('type','screen_share_start')->count())->toBe(1);});
it('stores transcript text and segments for an audio clip',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$channel=DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'Général','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$report=VoiceReport::query()->create(['discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-1','reporter_user_discord_id'=>'user-2','reason'=>'Test','status'=>'pending','reported_at'=>now()]);$clip=VoiceAudioClip::query()->create(['voice_report_id'=>$report->id,'discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-1','storage_path'=>'storage/audio-clips/test.wav','mime_type'=>'audio/wav','size_bytes'=>1024,'duration_seconds'=>3,'captured_from'=>now()->subSeconds(3),'captured_until'=>now(),'status'=>'captured']);$this->withToken('secret')->postJson('/api/v1/internal/transcripts',['voice_report_id'=>$report->id,'voice_audio_clip_id'=>$clip->id,'reported_user_discord_id'=>'user-1','status'=>'completed','text'=>'Bonjour le monde','language'=>'fr','engine'=>'test','segments'=>[['start_seconds'=>0,'end_seconds'=>1.5,'text'=>'Bonjour'],['start_seconds'=>1.5,'end_seconds'=>3,'text'=>'le monde']]])->assertCreated()->assertJsonPath('data.status','completed');$transcript=VoiceTranscript::query()->first();expect($transcript?->text)->toBe('Bonjour le monde')->and($transcript?->segments()->count())->toBe(2);});
it('returns pending transcript jobs for the worker',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$channel=DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'Général','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$report=VoiceReport::query()->create(['discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-1','reporter_user_discord_id'=>'user-2','reason'=>'Test','status'=>'pending','reported_at'=>now()]);$clip=VoiceAudioClip::query()->create(['voice_report_id'=>$report->id,'discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-1','storage_path'=>'storage/audio-clips/test.wav','mime_type'=>'audio/wav','size_bytes'=>1024,'duration_seconds'=>3,'captured_from'=>now()->subSeconds(3),'captured_until'=>now(),'status'=>'captured']);VoiceTranscript::query()->create(['voice_report_id'=>$report->id,'voice_audio_clip_id'=>$clip->id,'reported_user_discord_id'=>'user-1','status'=>'pending']);$this->withToken('secret')->getJson('/api/v1/internal/transcripts?limit=1')->assertOk()->assertJsonCount(1,'data')->assertJsonPath('data.0.storage_path','storage/audio-clips/test.wav');});
it('returns stale processing transcript jobs for retry',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$channel=DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'channel-1','name'=>'Général','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$report=VoiceReport::query()->create(['discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-1','reporter_user_discord_id'=>'user-2','reason'=>'Test','status'=>'pending','reported_at'=>now()]);$staleClip=VoiceAudioClip::query()->create(['voice_report_id'=>$report->id,'discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-1','storage_path'=>'storage/audio-clips/stale.wav','mime_type'=>'audio/wav','size_bytes'=>1024,'duration_seconds'=>3,'captured_from'=>now()->subSeconds(3),'captured_until'=>now(),'status'=>'captured']);$freshClip=VoiceAudioClip::query()->create(['voice_report_id'=>$report->id,'discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>'user-2','storage_path'=>'storage/audio-clips/fresh.wav','mime_type'=>'audio/wav','size_bytes'=>1024,'duration_seconds'=>3,'captured_from'=>now()->subSeconds(3),'captured_until'=>now(),'status'=>'captured']);VoiceTranscript::query()->create(['voice_report_id'=>$report->id,'voice_audio_clip_id'=>$staleClip->id,'reported_user_discord_id'=>'user-1','status'=>'processing','started_at'=>now()->subMinutes(11)]);VoiceTranscript::query()->create(['voice_report_id'=>$report->id,'voice_audio_clip_id'=>$freshClip->id,'reported_user_discord_id'=>'user-2','status'=>'processing','started_at'=>now()->subMinutes(2)]);$this->withToken('secret')->getJson('/api/v1/internal/transcripts?limit=5')->assertOk()->assertJsonCount(1,'data')->assertJsonPath('data.0.storage_path','storage/audio-clips/stale.wav');});
it('archives stale channels when the worker synchronizes a guild',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Ancien nom','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$stale=DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'old-channel','name'=>'Ancien vocal','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$this->withToken('secret')->postJson("/api/v1/internal/bots/{$bot->id}/guilds/guild-1/channels",['guild'=>['name'=>'Nouveau nom','owner_id'=>'new-owner'],'channels'=>[['id'=>'new-channel','name'=>'Nouveau vocal','type'=>2,'parent_id'=>null,'user_limit'=>8]]])->assertOk()->assertJsonPath('data.accepted',true);expect($stale->fresh()->is_monitored)->toBeFalse()->and($stale->fresh()->discord_bot_id)->toBeNull()->and($stale->fresh()->archived_at)->not->toBeNull()->and(DiscordChannel::query()->where('discord_id','new-channel')->whereNull('archived_at')->exists())->toBeTrue()->and($guild->fresh()->name)->toBe('Nouveau nom');});
it('keeps monitored channels when a worker sync receives no usable channels',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$channel=DiscordChannel::query()->create(['discord_guild_id'=>$guild->id,'discord_id'=>'voice-1','name'=>'Vocal gardé','type'=>'voice','is_monitored'=>true,'discord_bot_id'=>$bot->id]);$this->withToken('secret')->postJson("/api/v1/internal/bots/{$bot->id}/guilds/guild-1/channels",['channels'=>[]])->assertOk()->assertJsonPath('data.accepted',true);expect($channel->fresh()->is_monitored)->toBeTrue()->and($channel->fresh()->discord_bot_id)->toBe($bot->id)->and($channel->fresh()->archived_at)->toBeNull();});
it('applies global defaults to newly synchronized voice channels',function(){config(['services.worker.token'=>'secret']);AppSetting::query()->create(['key'=>'global','value'=>['defaults'=>['buffer_seconds'=>60,'retention_days'=>14,'volume_analysis_enabled'=>true,'transcription_enabled'=>true,'monitor_new_voice_channels'=>false]]]);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$guild=DiscordGuild::query()->create(['discord_id'=>'guild-1','name'=>'Guild','owner_discord_id'=>'owner','discord_bot_id'=>$bot->id]);$this->withToken('secret')->postJson("/api/v1/internal/bots/{$bot->id}/guilds/guild-1/channels",['channels'=>[['id'=>'new-channel','name'=>'Nouveau vocal','type'=>2]]])->assertOk();$channel=DiscordChannel::query()->where('discord_id','new-channel')->first();expect($channel?->buffer_seconds)->toBe(60)->and($channel?->retention_days)->toBe(14)->and($channel?->volume_analysis_enabled)->toBeTrue()->and($channel?->transcription_enabled)->toBeTrue()->and($channel?->is_monitored)->toBeFalse()->and($channel?->discord_bot_id)->toBeNull();});
it('creates a guild discovered by the worker during channel sync',function(){config(['services.worker.token'=>'secret']);$bot=DiscordBot::query()->create(['name'=>'Guardian','client_id'=>'123','token'=>'discord-secret','is_active'=>true]);$this->withToken('secret')->postJson("/api/v1/internal/bots/{$bot->id}/guilds/guild-2/channels",['guild'=>['name'=>'Guild découverte','owner_id'=>'owner-2'],'channels'=>[['id'=>'voice-1','name'=>'Vocal','type'=>2]]])->assertOk()->assertJsonPath('data.accepted',true);$guild=DiscordGuild::query()->where('discord_id','guild-2')->first();expect($guild?->name)->toBe('Guild découverte')->and($guild?->discord_bot_id)->toBe($bot->id)->and(DiscordChannel::query()->where('discord_id','voice-1')->exists())->toBeTrue();});
